#!/usr/bin/env bash
# Fresh start: start the Ditto cluster together and explicitly wait BEFORE init.
# Avoids the optional extended-api Git source build, whose pinned commit may not exist.
set -euo pipefail
cd "$(dirname "$0")/.."
bash scripts/compose-env.sh
ENV=deploy/compose/.env
PROJECT="${COMPOSE_PROJECT_NAME:-oreflow58}"
COMPOSE=(docker compose -p "$PROJECT" --env-file "$ENV" -f deploy/compose/docker-compose.yml -f team/oreflow/compose.yml)
set -a
# File is generated by our own credential utility; do not source arbitrary files.
source "$ENV"
set +a
"${COMPOSE[@]}" up -d mongodb influxdb mosquitto policies things things-search connectivity gateway ditto-nginx grafana telegraf
printf 'Waiting for five-node Ditto cluster readiness...\n'
ready=0
for attempt in $(seq 1 50); do
 if curl -fsS --max-time 5 -u "devops:$DITTO_DEVOPS_PASSWORD" "http://127.0.0.1:${DITTO_PORT:-8080}/status/health" >/dev/null 2>&1; then
  ready=1;break
 fi
 # Workaround for Akka contact-point bootstrap when gateway started too early.
 if [[ "$attempt" == 10 ]]; then
  echo 'Restarting gateway once after the other Ditto services have started...'
  "${COMPOSE[@]}" restart gateway
 fi
 sleep 10
done
if [[ "$ready" != 1 ]]; then
 echo 'Ditto API is not ready; preserving all containers and volumes for diagnosis.' >&2
 "${COMPOSE[@]}" ps >&2
 exit 1
fi
printf 'Ditto API is responding; initializing policies and MQTT connection...\n'
"${COMPOSE[@]}" up -d --no-deps --force-recreate init
id=$("${COMPOSE[@]}" ps -q init)
code=$(docker wait "$id")
if [[ "$code" != 0 ]]; then
 echo 'OpenEgiz init failed; inspect:' >&2
 docker logs --tail 70 "$id" >&2
 exit 1
fi
"${COMPOSE[@]}" build oreflow-setup
"${COMPOSE[@]}" up -d --no-build oreflow-setup oreflow
printf '\nOreFlow 2.3 competition dashboard: http://localhost:8099\n'
printf 'Grafana: http://localhost:3000/d/oreflow-northpit\n'
printf 'Verify: python3 tools/verify-oreflow.py\n'
